metadata.vgl:
vgraph c4Elements: C4 "The C4 element types" {
    node person: Person "Person";
    node extPerson: ExternalPerson "ExternalPerson";
    node system: SoftwareSystem "SoftwareSystem";
    node extSystem: ExternalSoftwareSystem "ExternalSoftwareSystem";
    node extContainer: ExternalContainer "ExternalContainer";

    group sb: SystemBoundary "SystemBoundary" {
        node container: Container "Container";
        node database: Database "Database";

        group cb: ContainerBoundary "ContainerBoundary" {
            node component: Component "Component";
            node extComponent: ExternalComponent "ExternalComponent";
            node code: CodeElement "CodeElement";
        };
    };

    edge person -> container "Uses";
    edge extPerson -> system "Uses";
    edge system -> container "Sends data to";
    edge container -> database "Reads from and writes to";
    edge container -> component "Uses";
    edge component -> extComponent "Uses";
    edge code -> component "Implements";
    edge extContainer -> container "Makes API calls to";
    edge container -> extSystem "Makes API calls to";
}
